from fractions import Fraction
from sympy import sqrt, simplify

def rref(M, cols):
    R = [[Fraction(x) for x in row] for row in M]
    pivots = []
    for c in range(cols):
        r = len(pivots)
        p = r
        while p < len(R) and R[p][c] == 0:
            p = p + 1
        if p == len(R):
            continue
        R[r], R[p] = R[p], R[r]
        k = R[r][c]
        R[r] = [x / k for x in R[r]]
        for i in range(len(R)):
            k = R[i][c]
            if i != r and k != 0:
                R[i] = [R[i][j] - k * R[r][j] for j in range(len(R[i]))]
        pivots.append(c)
    return R, pivots

def vec(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def null(A):
    n = len(A[0])
    R, pivots = rref(A, n)
    free = [j for j in range(n) if j not in pivots]
    print(f"  pivot columns {[p + 1 for p in pivots]}, free columns {[f + 1 for f in free]}")
    if not free:
        print("  no free variable, so N(A) holds only the zero vector")
    for f in free:
        s = [Fraction(0)] * n
        s[f] = Fraction(1)
        for i in range(len(pivots)):
            s[pivots[i]] = -R[i][f]
        print(f"  x{f + 1} = 1 gives the special solution {vec(s)}")

def independence(vectors):
    m, k = len(vectors[0]), len(vectors)
    r = len(rref([[v[i] for v in vectors] for i in range(m)], k)[1])
    print(f"  {r} pivot(s) for {k} vectors in R^{m}")
    print("  a pivot in every column: independent" if r == k else "  a free column: dependent")
    print("  a pivot in every row: they span" if r == m else "  a row with no pivot: they don't span")

def eigenvalues(A):
    t = A[0][0] + A[1][1]
    d = A[0][0] * A[1][1] - A[0][1] * A[1][0]
    disc = t * t - 4 * d
    print(f"  trace {t}, det {d}, so λ^2 - ({t})λ + ({d}) = 0, discriminant {disc}")
    if disc < 0:
        print("  negative: complex eigenvalues, so no real eigenvectors")
    elif disc == 0:
        print(f"  zero: one repeated eigenvalue {t / 2}")
    else:
        l1, l2 = simplify((t + sqrt(disc)) / 2), simplify((t - sqrt(disc)) / 2)
        print(f"  λ = {l1} and {l2}, sum {simplify(l1 + l2)}, product {simplify(l1 * l2)}")

count = int(input())
for t in range(count):
    kind, size = input().split()
    rows = [[Fraction(w) for w in input().split()] for i in range(int(size))]
    print(f"Problem {t + 1}: {kind} {', '.join(vec(row) for row in rows)}")
    if kind == "null":
        null(rows)
    elif kind == "independence":
        independence(rows)
    else:
        eigenvalues(rows)

