from fractions import Fraction

def vec(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def show(M):
    return "  ".join("[" + ", ".join(str(x) for x in row) + "]" for row in M)

def dot(u, v):
    return sum(u[i] * v[i] for i in range(len(u)))

def mul(A, B):
    return [[sum(A[i][k] * B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]

def inverse2(P):
    a, b = P[0]
    c, d = P[1]
    det = a * d - b * c
    return [[d / det, -b / det], [-c / det, a / det]]

def similar(rows):
    A = rows[:2]
    P = [[rows[2][0], rows[3][0]], [rows[2][1], rows[3][1]]]
    D = mul(inverse2(P), mul(A, P))
    print(f"  A P = {show(mul(A, P))}, then P^-1 A P = {show(D)}")
    print(f"  trace {A[0][0] + A[1][1]} and {D[0][0] + D[1][1]}, det {A[0][0] * A[1][1] - A[0][1] * A[1][0]} and {D[0][0] * D[1][1] - D[0][1] * D[1][0]}")
    print("  diagonal: the basis vectors are eigenvectors" if D[0][1] == 0 and D[1][0] == 0 else "  not diagonal")

def power(rows):
    A, v1, v2, lams, x, k = rows[:2], rows[2], rows[3], rows[4], rows[5], int(rows[6][0])
    P = [[v1[0], v2[0]], [v1[1], v2[1]]]
    c = [row[0] for row in mul(inverse2(P), [[x[0]], [x[1]]])]
    print(f"  eigen-coordinates: x = ({c[0]}){vec(v1)} + ({c[1]}){vec(v2)}")
    Akx = [c[0] * lams[0] ** k * v1[i] + c[1] * lams[1] ** k * v2[i] for i in range(2)]
    print(f"  A^{k} x = ({c[0]})({lams[0]})^{k}{vec(v1)} + ({c[1]})({lams[1]})^{k}{vec(v2)} = {vec(Akx)}")
    y = x
    for step in range(k):
        y = [dot(row, y) for row in A]
    print(f"  check by {k} multiplications: {vec(y)}, {y == Akx}")

def gram(rows):
    xs, x = rows[:-1], rows[-1]
    vs = []
    for w in xs:
        v = list(w)
        for u in vs:
            c = dot(w, u) / dot(u, u)
            v = [v[i] - c * u[i] for i in range(len(v))]
        if any(t != 0 for t in v):
            vs.append(v)
        else:
            print(f"  {vec(w)} leaves (0): it depends on the others, so drop it")
    print(f"  Gram-Schmidt: {', '.join(vec(v) for v in vs)}")
    p = [sum(dot(x, u) / dot(u, u) * u[i] for u in vs) for i in range(len(x))]
    e = [x[i] - p[i] for i in range(len(x))]
    print(f"  projection of {vec(x)}: p = {vec(p)}, e = {vec(e)}, e . v = {', '.join(str(dot(e, v)) for v in vs)}")

count = int(input())
for t in range(count):
    kind, size = input().split()
    rows = [[Fraction(w) for w in input().split()] for i in range(int(size))]
    print(f"Problem {t + 1}: {kind} {', '.join(vec(row) for row in rows)}")
    if kind == "similar":
        similar(rows)
    elif kind == "power":
        power(rows)
    else:
        gram(rows)

